import { useSyncExternalStore } from 'react'
import { registerSW } from 'virtual:pwa-register'

/**
 * The service worker (generated by vite-plugin-pwa, see vite.config.ts). It
 * precaches the built shell so the app opens offline and starts instantly once
 * installed. A new build does not take over on its own: the worker waits, the
 * app shows "a new version is ready" (`useUpdateReady`) and the user applies it
 * with a tap (`applyUpdate`), which hard-refreshes the page onto the new build.
 *
 * The notice is off by default; someone who wants to be asked turns it on
 * (`setUpdateNotices`, the Notifications sheet, remembered per browser as
 * `karpul.updateNotices`). While it is off nothing is shown and a waiting build is taken only in the first seconds
 * after the app opens (`QUIET_WINDOW_MS`), before anything has been typed, so
 * an update lands the next time the app is started and never under a finger.
 * That quiet take (`takeQuietly`) reloads only once the new worker has really
 * taken the page, and is tried once per `QUIET_RETRY_MS` in a tab: an iOS app
 * woken from the background can keep its new worker waiting, and a reload
 * regardless found it still waiting and reloaded again, every few seconds.
 *
 * In `npm run dev` the virtual module is a stub and none of this runs.
 */

const CHECK_EVERY_MS = 60 * 60 * 1000
/** How long a tap waits for the new worker before reloading regardless. */
const RELOAD_AFTER_MS = 3000

/** With the notice off, how soon after start a waiting build is still taken. */
const QUIET_WINDOW_MS = 10_000
/** How long the quiet take waits for the new worker before giving up until the next start. */
const QUIET_WAIT_MS = 10_000
/** A tab tries the quiet take at most once this often, whatever happened last time. */
const QUIET_RETRY_MS = 10 * 60 * 1000
const QUIET_KEY = 'karpul.quietUpdate'
const NOTICES_KEY = 'karpul.updateNotices'
const startedAt = Date.now()

/** Off unless this browser turned it on: most people would rather the app just update. */
function loadNotices(): boolean {
  try {
    return localStorage.getItem(NOTICES_KEY) === 'on'
  } catch {
    return false
  }
}

let notices = loadNotices()
let ready = false
let update: ((reloadPage?: boolean) => Promise<void>) | null = null
let applying = false
const listeners = new Set<() => void>()

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

/** Registers the worker once; call from main.tsx. */
export function startServiceWorker() {
  if (!('serviceWorker' in navigator)) return
  update = registerSW({
    onNeedRefresh() {
      ready = true
      listeners.forEach((l) => l())
      if (!notices && Date.now() - startedAt < QUIET_WINDOW_MS) takeQuietly()
    },
    onRegisteredSW(_url, registration) {
      if (!registration) return
      // An installed app can stay open for days, so ask for a new build every
      // hour and whenever the app comes back to the foreground.
      const check = () => {
        if (document.visibilityState === 'visible' && navigator.onLine) registration.update().catch(() => {})
      }
      setInterval(check, CHECK_EVERY_MS)
      document.addEventListener('visibilitychange', check)
    },
  })
}

/** Is the "new version is ready" card (and its bolt) wanted in this browser? */
export function useUpdateNotices(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => notices,
    () => false,
  )
}

export function setUpdateNotices(on: boolean) {
  notices = on
  try {
    localStorage.setItem(NOTICES_KEY, on ? 'on' : 'off')
  } catch {
    /* private mode: for this visit only */
  }
  listeners.forEach((l) => l())
}

/** True once a newer build is installed and waiting. */
export function useUpdateReady(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => ready,
    () => false,
  )
}

/**
 * Empties the Cache Storage so the reload comes off the network. Workbox's
 * precache is what an ordinary reload would be served from, so clearing it is
 * what makes this a *hard* refresh; the new worker fills it again on the way
 * back. Skipped when the browser says it is offline, where the precache is the
 * only copy of the app there is.
 */
async function dropCaches() {
  if (!('caches' in window) || navigator.onLine === false) return
  try {
    const names = await caches.keys()
    await Promise.all(names.map((name) => caches.delete(name)))
  } catch {
    // A browser with site data blocked. Reload on what it has.
  }
}

/** Was the quiet take tried in this tab a moment ago? Records this try when not. */
function triedQuietly(): boolean {
  try {
    const last = Number(sessionStorage.getItem(QUIET_KEY))
    if (last && Date.now() - last < QUIET_RETRY_MS) return true
    sessionStorage.setItem(QUIET_KEY, String(Date.now()))
    return false
  } catch {
    // No storage to remember a try by: never risk a reload loop.
    return true
  }
}

/**
 * The update nobody asked for, at start: the waiting worker is told to take
 * over and the page reloads when it has, and only then. No timer and no cache
 * clearing, unlike a tap: when the worker stays waiting (iOS after a long sleep)
 * the page is left alone and the build lands on the next start.
 */
function takeQuietly() {
  if (applying || !update || !('serviceWorker' in navigator) || triedQuietly()) return
  const sw = navigator.serviceWorker
  const reload = () => {
    if (!applying) window.location.reload()
  }
  sw.addEventListener('controllerchange', reload, { once: true })
  setTimeout(() => sw.removeEventListener('controllerchange', reload), QUIET_WAIT_MS)
  void update().catch(() => {})
}

/**
 * Hands the page over to the waiting build and hard-refreshes onto it. The
 * reload is ours: the plugin only reloads when a worker already controlled the
 * page at registration, which is false on a first visit, and a tap must never
 * do nothing. `clientsClaim` (vite.config.ts) makes the new worker take the
 * page, which is what fires `controllerchange` here; the timer is the promise
 * that the tap refreshes anyway when it does not (no worker waiting any more,
 * a lost message, a browser that never claims). Whichever lands first wins,
 * once.
 */
export function applyUpdate() {
  if (applying) return
  applying = true

  let timer: ReturnType<typeof setTimeout> | undefined
  let reloading = false
  const reload = () => window.location.reload()
  const hardReload = () => {
    if (reloading) return
    reloading = true
    if (timer !== undefined) clearTimeout(timer)
    void dropCaches().then(reload, reload)
  }

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.addEventListener('controllerchange', hardReload, { once: true })
  }
  timer = setTimeout(hardReload, RELOAD_AFTER_MS)
  if (update) void update().catch(hardReload)
  else hardReload()
}
